// Loom works in linear light and straight alpha (SPEC V56). TouchDesigner's TOPs hold
// sRGB-encoded 8-bit values, and every operator in drmbt's network does its maths on those
// numbers. wgsl_encode and wgsl_decode bracket the TD chain so a threshold of 0.05, a
// brightness of 1.64, a soft light and an emboss all mean exactly what they meant in TD.
// This half: sRGB-encoded values -> linear, back into the project's working space.
struct Params {
  amount: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

fn decodeSrgb(encoded: vec3f) -> vec3f {
  let c = clamp(encoded, vec3f(0.0), vec3f(1.0));
  let high = pow((c + vec3f(0.055)) / 1.055, vec3f(2.4));
  return select(high, c / 12.92, c <= vec3f(0.04045));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let source = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  // Amount must match wgsl_encode's: 1 decodes, 0 passes the values through.
  return vec4f(mix(source.rgb, decodeSrgb(source.rgb), params.amount), source.a);
}

// Loom works in linear light and straight alpha (SPEC V56). TouchDesigner's TOPs hold
// sRGB-encoded 8-bit values, and every operator in drmbt's network does its maths on those
// numbers. wgsl_encode and wgsl_decode bracket the TD chain so a threshold of 0.05, a
// brightness of 1.64, a soft light and an emboss all mean exactly what they meant in TD.
// This half: linear -> sRGB-encoded values (the exact piecewise sRGB curve).
struct Params {
  amount: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

fn encodeSrgb(linear: vec3f) -> vec3f {
  let c = clamp(linear, vec3f(0.0), vec3f(1.0));
  let high = (1.055 * pow(c, vec3f(1.0 / 2.4))) - vec3f(0.055);
  return select(high, c * 12.92, c <= vec3f(0.0031308));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let source = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let plain = clamp(source.rgb, vec3f(0.0), vec3f(1.0));
  // Amount 1 encodes. 0 leaves linear values in place, to A/B the TD maths against Loom's.
  return vec4f(mix(plain, encodeSrgb(source.rgb), params.amount), source.a);
}

