// TD Composite TOP, operation Maximum (comp2 in drmbt's watercolor): per channel
// max(a, b), alpha included, as TD returns it. a is input 0 (the grained input), b is
// input 1 (the bled feedback, wired into More). This node is also what the feedback
// records, so the trail can only ever brighten the picture under it.
struct Params {
  amount: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

fn secondAt(uv: vec2f) -> vec4f {
  let size = vec2i(textureDimensions(inputTexture1));
  let texel = clamp(vec2i(uv * vec2f(size)), vec2i(0), size - vec2i(1));
  return textureLoad(inputTexture1, texel, 0);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let a = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let b = secondAt(uv);
  // Amount mixes from input 0 alone (0) to the full maximum (1).
  return mix(a, max(a, b), params.amount);
}

// TD Composite TOP, operation Soft Light (comp3 in drmbt's watercolor).
// Measured in TD 2025.33230 on two ramps: per channel (1 - 2b) * a^2 + 2b * a, the Pegtop
// form rather than the W3C one, where a is input 0 (the base: the drifted feedback) and
// b is input 1 (the blend: the grained input, wired into More). Alpha is input 0's.
struct Params {
  amount: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

fn secondAt(uv: vec2f) -> vec4f {
  let size = vec2i(textureDimensions(inputTexture1));
  let texel = clamp(vec2i(uv * vec2f(size)), vec2i(0), size - vec2i(1));
  return textureLoad(inputTexture1, texel, 0);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let a = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let b = secondAt(uv);
  let soft = ((vec3f(1.0) - (2.0 * b.rgb)) * a.rgb * a.rgb) + (2.0 * b.rgb * a.rgb);
  // Amount mixes from the base (0) to the full soft light (1).
  return vec4f(mix(a.rgb, soft, params.amount), a.a);
}

// [RGB | skeleton] side by side, the frame sd-webrtc's control packing splits into the
// picture it diffuses (left) and the ControlNet map (right). Main input: the RGB half;
// inputTexture1: the skeleton. The node is twice as wide as it is high.
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  if (uv.x < 0.5) {
    let rgb = textureSampleLevel(inputTexture, inputSampler, vec2f(uv.x * 2.0, uv.y), 0.0);
    return vec4f(rgb.rgb, 1.0);
  }
  let size = vec2i(textureDimensions(inputTexture1));
  let at = vec2i(vec2f((uv.x - 0.5) * 2.0, uv.y) * vec2f(size));
  return vec4f(textureLoad(inputTexture1, clamp(at, vec2i(0), size - vec2i(1)), 0).rgb, 1.0);
}

// OpenPose-18 skeleton of MoveNet's 17 COCO keypoints, the format the openpose ControlNet
// was trained on, drawn as realtime-client's Sense clip draws it (src/lib/senseOverlay.ts):
// limbs at 0.85 alpha in the canonical palette, then opaque joints, on black. The main input
// is the square the RGB half shows, for the size and the orientation (never flipped);
// inputTexture1 is MoveNet's 17x1 keypoint map: x, y in 0..1 with y down, confidence in blue.
struct Params {
  size: f32, // @default 20  Base scale in pixels: limbs max(4, size x 0.45) wide, joints max(3, size x 0.4) in radius.
  threshold: f32, // @default 0.4  A joint is drawn above this confidence.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

// The COCO-17 joint for each OpenPose-18 slot; -1 is the neck, the shoulders' midpoint.
const COCO_TO_OP = array<i32, 18>(0, -1, 6, 8, 10, 5, 7, 9, 12, 14, 16, 11, 13, 15, 2, 1, 4, 3);
const PAIRS = array<vec2<i32>, 17>(
  vec2<i32>(1, 2), vec2<i32>(1, 5), vec2<i32>(2, 3), vec2<i32>(3, 4), vec2<i32>(5, 6), vec2<i32>(6, 7),
  vec2<i32>(1, 8), vec2<i32>(8, 9), vec2<i32>(9, 10), vec2<i32>(1, 11), vec2<i32>(11, 12), vec2<i32>(12, 13),
  vec2<i32>(1, 0), vec2<i32>(0, 14), vec2<i32>(14, 16), vec2<i32>(0, 15), vec2<i32>(15, 17));
// The canonical OpenPose palette, sRGB 0..255: limb j and joint k take entry j and k.
const COLORS = array<vec3f, 18>(
  vec3f(255.0, 0.0, 0.0), vec3f(255.0, 85.0, 0.0), vec3f(255.0, 170.0, 0.0), vec3f(255.0, 255.0, 0.0),
  vec3f(170.0, 255.0, 0.0), vec3f(85.0, 255.0, 0.0), vec3f(0.0, 255.0, 0.0), vec3f(0.0, 255.0, 85.0),
  vec3f(0.0, 255.0, 170.0), vec3f(0.0, 255.0, 255.0), vec3f(0.0, 170.0, 255.0), vec3f(0.0, 85.0, 255.0),
  vec3f(0.0, 0.0, 255.0), vec3f(85.0, 0.0, 255.0), vec3f(170.0, 0.0, 255.0), vec3f(255.0, 0.0, 255.0),
  vec3f(255.0, 0.0, 170.0), vec3f(255.0, 0.0, 85.0));

fn keypoint(index: i32) -> vec3f {
  return textureLoad(inputTexture1, vec2i(index, 0), 0).xyz;
}

// OpenPose-18 joint `slot`: xy in 0..1 (y down), z its confidence. The neck takes the
// lower of the two shoulders' confidences.
fn joint(slot: i32) -> vec3f {
  var map = COCO_TO_OP;
  let coco = map[slot];
  if (coco < 0) {
    let left = keypoint(5);
    let right = keypoint(6);
    return vec3f((left.xy + right.xy) * 0.5, min(left.z, right.z));
  }
  return keypoint(coco);
}

fn segment(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
  return length(pa - ba * h);
}

fn decodeSrgb(encoded: vec3f) -> vec3f {
  let c = clamp(encoded, vec3f(0.0), vec3f(1.0));
  let high = pow((c + vec3f(0.055)) / 1.055, vec3f(2.4));
  return select(high, c / 12.92, c <= vec3f(0.04045));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let size = vec2f(textureDimensions(inputTexture));
  // The node binds its main input with a sampler; one read keeps that binding in the layout.
  // The picture itself is not drawn: the skeleton goes on black.
  let unused = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).a * 0.0;
  let at = uv * size;
  let width = max(4.0, params.size * 0.45);
  let radius = max(3.0, params.size * 0.4);
  var pairs = PAIRS;
  var colors = COLORS;
  // A 2D canvas blends in sRGB, so the strokes mix there and are decoded once at the end:
  // the stream then carries the palette's own bytes.
  var color = vec3f(0.0);
  for (var j = 0; j < 17; j++) {
    let a = joint(pairs[j].x);
    let b = joint(pairs[j].y);
    if (a.z <= params.threshold || b.z <= params.threshold) { continue; }
    let d = segment(at, a.xy * size, b.xy * size);
    let cover = 1.0 - smoothstep(width * 0.5 - 0.5, width * 0.5 + 0.5, d);
    color = mix(color, colors[j] / 255.0, 0.85 * cover);
  }
  for (var k = 0; k < 18; k++) {
    let p = joint(k);
    if (p.z <= params.threshold) { continue; }
    let cover = 1.0 - smoothstep(radius - 0.5, radius + 0.5, length(at - p.xy * size));
    color = mix(color, colors[k] / 255.0, cover);
  }
  return vec4f(decodeSrgb(color) + vec3f(unused), 1.0);
}
